INSERT INTO permisos_roles(rol_id,permiso_id) SELECT r.id,p.id FROM roles r CROSS JOIN permisos p WHERE r.nombre='Super Admin';
INSERT INTO permisos_roles(rol_id,permiso_id) SELECT r.id,p.id FROM roles r CROSS JOIN permisos p WHERE r.nombre='Doctor' AND p.nombre IN ('recetas.read','recetas.create','recetas.update','recetas.delete','antecedentes.read','antecedentes.create','antecedentes.update','antecedentes.delete','pacientes.read','medicos.read','horarios.read','citas.read','informes.read');
INSERT INTO permisos_roles(rol_id,permiso_id) SELECT r.id,p.id FROM roles r CROSS JOIN permisos p WHERE r.nombre='Patient' AND p.nombre IN ('medicos.read','pacientes.read','antecedentes.read','seguros.read','informes.read','horarios.read','citas.read','recetas.read','facturas.read');
INSERT INTO permisos_roles(rol_id,permiso_id) SELECT r.id,p.id FROM roles r CROSS JOIN permisos p WHERE r.nombre='Accountant' AND p.nombre IN ('cuentas.read','cuentas.create','cuentas.update','cuentas.delete','facturas.read','facturas.create','facturas.update','facturas.delete','pagos.read','pagos.create','pagos.update','pagos.delete','reportes.read','pacientes.read','seguros.read','monedas.read','impuestos.read');
INSERT INTO permisos_roles(rol_id,permiso_id) SELECT r.id,p.id FROM roles r CROSS JOIN permisos p WHERE r.nombre='Laboratorist' AND p.nombre IN ('informes.read','informes.create','informes.update','informes.delete','plantillas-laboratorio.read','plantillas-laboratorio.create','plantillas-laboratorio.update','plantillas-laboratorio.delete','medicos.read','pacientes.read','antecedentes.read');
INSERT INTO permisos_roles(rol_id,permiso_id) SELECT r.id,p.id FROM roles r CROSS JOIN permisos p WHERE r.nombre='Receptionist' AND p.nombre IN ('pacientes.read','pacientes.create','pacientes.update','pacientes.delete','antecedentes.read','antecedentes.create','antecedentes.update','antecedentes.delete','horarios.read','horarios.create','horarios.update','horarios.delete','citas.read','citas.create','citas.update','citas.delete','medicos.read','informes.read','recetas.read');
